  '1h333nq85ni': R`<p>للتقريب إلى منزلة ما، انظر إلى الرقم <b>الذي يليها مباشرة على اليمين</b>.</p><ul><li>5 أو أكثر: نقرّب <b>إلى الأعلى</b> (نزيد رقم المنزلة واحدًا).</li><li>4 أو أقل: نقرّب <b>إلى الأدنى</b> (يبقى رقم المنزلة كما هو).</li></ul><p>تصبح كل الأرقام بعد منزلة التقريب أصفارًا.</p>`,
  '264ckm0rxdd': R`<p>قرّب 3,462 إلى أقرب مئة.</p><ol><li>رقم المئات هو 4، والرقم الذي على يمينه (العشرات) هو 6.</li><li>6 أكبر من 5 أو يساويها، لذا نقرّب إلى الأعلى: يصبح الرقم 4 هو 5.</li><li>الجواب: <b>3,500</b>.</li></ol><p>وإلى أقرب عشرة يصبح 3,462 هو 3,460، وإلى أقرب ألف يصبح 3,000.</p>`,
  '1b014azrv9g': R`<p>انظر إلى الرقم التالي فقط. العدد 3,449 مقرّبًا إلى أقرب مئة هو 3,400 وليس 3,500 — لا تقرّب على مراحل أبدًا.</p>`,
