  // add-sub
  '2crp1hgq6k1': R`
<p>الجمع يضم الكميات معًا؛ والطرح يجد الباقي أو <b>الفرق</b> بين كميتين. للأعداد الكبيرة نستخدم <b>الطريقة العمودية</b>: نرتّب الأرقام حسب منازلها ونبدأ من عمود الآحاد متجهين إلى اليسار.</p>
<h3>الجمع مع الحمل</h3>
<p>إذا بلغ مجموع عمود 10 أو أكثر، نكتب رقم الآحاد و<b>نحمل</b> العشرة إلى العمود التالي.</p>
⟦0⟧
<h3>الطرح مع الاستلاف</h3>
<p>إذا كان الرقم العلوي في عمود أصغر من السفلي، <b>نستلف</b> واحدًا من العمود التالي، فيزيد العمود الحالي 10.</p>
⟦1⟧
⟦2⟧
<h3>المسائل اللفظية</h3>
<p>كلمات مثل <i>معًا، المجموع، أكثر، زاد</i> تدل غالبًا على الجمع. وكلمات مثل <i>بقي، الباقي، الفرق، بكم يزيد، أقل</i> تدل غالبًا على الطرح. اسأل نفسك دائمًا عمّا يطلبه السؤال فعلًا.</p>
⟦3⟧`,
  '12bc1hhhzgf': R`<p>$4{,}587 + 2{,}846$</p><ol><li>الآحاد: $7 + 6 = 13$ ← نكتب 3 ونحمل 1.</li><li>العشرات: $8 + 4 + 1 = 13$ ← نكتب 3 ونحمل 1.</li><li>المئات: $5 + 8 + 1 = 14$ ← نكتب 4 ونحمل 1.</li><li>الآلاف: $4 + 2 + 1 = 7$.</li></ol><p>الجواب: <b>7,433</b>.</p>`,
  'dzfcdnot25': R`<p>$6{,}204 - 1{,}758$</p><ol><li>الآحاد: 4 أصغر من 8. رقم العشرات 0، لذا نستلف من المئات: يصبح 204 مئة واحدة و9 عشرات و14 آحادًا. $14 - 8 = 6$.</li><li>العشرات: $9 - 5 = 4$.</li><li>المئات: 1 أصغر من 7، لذا نستلف ألفًا: $11 - 7 = 4$.</li><li>الآلاف: $5 - 1 = 4$.</li></ol><p>الجواب: <b>4,446</b>.</p>`,
  '1myl5xbp4pm': R`<p>الجمع والطرح عمليتان عكسيتان. نتحقق من الطرح بالجمع: $4{,}446 + 1{,}758 = 6{,}204$ ✓. وبهذا نجد الأعداد المجهولة أيضًا: إذا كان $\square + 348 = 1{,}000$ فإن $\square = 1{,}000 - 348 = 652$.</p>`,
  '23w41b37di3': R`<p>من الأخطاء الشائعة طرح الرقم الأصغر من الأكبر في كل عمود (مثل كتابة $52 - 38 = 26$). الصواب هو الاستلاف: $52 - 38 = 14$.</p>`,
  'jzpsrz7qv': R`احسب $⟦0⟧ + ⟦1⟧$.`,
  '11vnennk127': R`رتّب الأرقام حسب منازلها واجمع بدءًا من الآحاد، واحمل كلما بلغ عمود 10 أو أكثر: $⟦0⟧ + ⟦1⟧ = ⟦2⟧$.`,
  '2cqlmyuanc4': R`احسب $⟦0⟧ - ⟦1⟧$.`,
  '217um699krb': R`اطرح عمودًا عمودًا بدءًا من الآحاد، واستلف حين يكون الرقم العلوي أصغر: $⟦0⟧ - ⟦1⟧ = ⟦2⟧$. التحقق: $⟦3⟧ + ⟦4⟧ = ⟦5⟧$.`,
  '20q2iwal3wx': R`ما العدد الذي يوضع في المربع؟ $\square + ⟦0⟧ = ⟦1⟧$`,
  '2vzsixgbwq': R`الطرح عكس الجمع: $⟦0⟧ - ⟦1⟧ = ⟦2⟧$.`,
  '19k8gxx8enm': R`كان عدد الكتب في مكتبة ⟦0⟧. وصلها ⟦1⟧ من الكتب الجديدة، ثم أعارت ⟦2⟧ منها. كم كتابًا بقي في المكتبة؟`,
  '22c2nbk22nn': R`نضيف الكتب الجديدة ثم نطرح المُعارة: $⟦0⟧ + ⟦1⟧ - ⟦2⟧ = ⟦3⟧$.`,
  'tjgizs9fjl': R`ميا`,
  '1if8m7vmopf': R`ليو`,
  '12t8l5omzh1': R`ساري`,
  '26mi5um5hxm': R`بودي`,
  '5ladyusi9v': R`آنا`,
