  '28xor3epndt': R`ديوي`,
  'fl1dlgr4st': R`راكا`,
  'b83c8sskmz': R`في لعبة، كانت نقاط ⟦0⟧: ⟦1⟧، ونقاط ⟦2⟧: ⟦3⟧. بكم نقطة تزيد نقاط ⟦4⟧؟`,
