  '100vdkuw7cv': R`الخطوة`,
  '1ata9ppdhpl': R`العملية`,
  '1i56r47suu5': R`مثال`,
  'bct94f2duc': R`الأقواس`,
  '152taipeiq': R`القوى والجذور`,
  '1dq9oio2vod': R`الضرب والقسمة — من اليسار إلى اليمين`,
  'ety1fhjk85': R`الجمع والطرح — من اليسار إلى اليمين`,
  '20c9xxbu7nh': R`<p>للضرب والقسمة الأولوية <b>نفسها</b>، وكذلك الجمع والطرح. وفي المستوى نفسه نحسب من <b>اليسار إلى اليمين</b> كما يُكتب التعبير الرياضي.</p>`,
  'vpi6gbf1j5': R`<p>احسب $20 - 8 \div 2 \times 3 + 1$.</p><ol><li>القسمة والضرب أولًا من اليسار إلى اليمين: $8 \div 2 = 4$، ثم $4 \times 3 = 12$.</li><li>يبقى $20 - 12 + 1$ من اليسار إلى اليمين: $8 + 1 = 9$.</li></ol><p>الجواب: <b>9</b>.</p>`,
  'cx7umbw06o': R`<p>احسب $(8 + 4) \times 3 - 2^3$.</p><ol><li>الأقواس: $8 + 4 = 12$.</li><li>القوى: $2^3 = 8$.</li><li>الضرب: $12 \times 3 = 36$.</li><li>الطرح: $36 - 8 = 28$.</li></ol>`,
  '9qyvtl39mt': R`<p>«PEMDAS» لا تعني الضرب قبل القسمة. $12 \div 3 \times 2 = 8$ وليس $12 \div 6 = 2$.</p>`,
  '2boesugt2g3': R`احسب $⟦0⟧ + ⟦1⟧ \times ⟦2⟧$.`,
  '18k6kdrqfh9': R`الضرب أولًا: $⟦0⟧ \times ⟦1⟧ = ⟦2⟧$. ثم الجمع: $⟦3⟧ + ⟦4⟧ = ⟦5⟧$.`,
  '13w7u6yvf66': R`احسب $(⟦0⟧ + ⟦1⟧) \times ⟦2⟧ - ⟦3⟧$.`,
  '1kgg8vz8ven': R`الأقواس: $⟦0⟧ + ⟦1⟧ = ⟦2⟧$. الضرب: $⟦3⟧ \times ⟦4⟧ = ⟦5⟧$. الطرح: $⟦6⟧ - ⟦7⟧ = ⟦8⟧$.`,
  'fpzk0whg2k': R`احسب $⟦0⟧ - ⟦1⟧ \div ⟦2⟧ \times ⟦3⟧$.`,
  '6i0q5bykj1': R`القسمة والضرب أولًا من اليسار إلى اليمين: $⟦0⟧ \div ⟦1⟧ = ⟦2⟧$، ثم $⟦3⟧ \times ⟦4⟧ = ⟦5⟧$. وأخيرًا $⟦6⟧ - ⟦7⟧ = ⟦8⟧$.`,
  '1f77fy0xem': R`احسب $⟦0⟧ + ⟦1⟧^2 - ⟦2⟧$.`,
  'isber9l7mx': R`القوى أولًا: $⟦0⟧^2 = ⟦1⟧$. ثم من اليسار إلى اليمين: $⟦2⟧ + ⟦3⟧ - ⟦4⟧ = ⟦5⟧$.`,
  '12cd51d72z4': R`احسب $⟦0⟧ \times (⟦1⟧ + ⟦2⟧) \div ⟦3⟧$.`,
  '1rwp21i838c': R`الأقواس: $⟦0⟧ + ⟦1⟧ = ⟦2⟧$. ثم من اليسار إلى اليمين: $⟦3⟧ \times ⟦4⟧ = ⟦5⟧$ و$⟦6⟧ \div ⟦7⟧ = ⟦8⟧$.`,
  '16yj15t3yvl': R`احسب $⟦0⟧ - ⟦1⟧ + ⟦2⟧$.`,
  '2g7vu4g2g7r': R`للجمع والطرح الأولوية نفسها، لذا نحسب من اليسار إلى اليمين: $⟦0⟧ - ⟦1⟧ = ⟦2⟧$، ثم $⟦3⟧ + ⟦4⟧ = ⟦5⟧$. ولو جمعنا $⟦6⟧ + ⟦7⟧$ أولًا لحصلنا خطأً على ⟦8⟧.`,

  // factors
  'obrpwbkvog': R`
<p><b>القاسم</b> (أو العامل) لعدد ما يقسمه قسمة تامة. و<b>المضاعف</b> لعدد ما هو ناتج ضربه في عدد طبيعي.</p>
<ul><li>قواسم 12: 1، 2، 3، 4، 6، 12 (تأتي أزواجًا: $1 \times 12$، $2 \times 6$، $3 \times 4$).</li><li>مضاعفات 12: 12، 24، 36، 48، …</li></ul>
<h3>الأعداد الأولية والأعداد غير الأولية</h3>
<p>للعدد <b>الأولي</b> قاسمان فقط: 1 والعدد نفسه (2، 3، 5، 7، 11، 13، …). وللعدد <b>غير الأولي</b> (المؤلَّف) أكثر من قاسمين. العدد 1 ليس أوليًا ولا مؤلَّفًا، و2 هو العدد الأولي الزوجي الوحيد.</p>
⟦0⟧
<h3>التحليل إلى العوامل الأولية</h3>
<p>يمكن كتابة كل عدد طبيعي أكبر من 1 حاصلَ ضرب أعداد أولية بطريقة واحدة فقط. استخدم شجرة العوامل: واصل التحليل حتى ينتهي كل فرع بعدد أولي.</p>
⟦1⟧
<h3>القاسم المشترك الأكبر والمضاعف المشترك الأصغر</h3>
⟦2⟧
⟦3⟧
⟦4⟧`,
