  'clxur1r60o': R`اكتبها كلها بثلاث منازل عشرية: ⟦0⟧. الأصغر هو <b>⟦1⟧</b>.`,

  // percent
  'r0jl598zxh': R`
<p><b>النسبة المئوية</b> تعني «من كل 100»: $35\% = \frac{35}{100} = 0.35$.</p>
⟦0⟧
<h3>الأسئلة الأساسية الثلاثة</h3>
⟦1⟧
⟦2⟧
<h3>الزيادة والنقصان والخصم</h3>
<p>خصم $20\%$ على 80 دولارًا يوفّر $0.2 \times 80 = 16$ دولارًا، فيصبح السعر بعد الخصم $80 - 16 = 64$ دولارًا. وبطريقة أسرع: تدفع $80\%$ من السعر، أي $0.8 \times 80 = 64$.</p>
<p>الزيادة بنسبة $p\%$ تعني الضرب في $1 + \frac{p}{100}$، والنقصان يعني الضرب في $1 - \frac{p}{100}$.</p>
⟦3⟧`,
  '2e1ivkcc9wi': R`كسر`,
  '21lfn42y4af': R`عدد عشري`,
  '1vaz29jk1go': R`نسبة مئوية`,
  '1lj32zs95qv': R`<ul><li><b>نسبة مئوية من كمية:</b> $p\% \text{ من } N = \frac{p}{100} \times N$.</li><li><b>ما النسبة المئوية لـ $a$ من $b$؟</b> $\frac{a}{b} \times 100\%$.</li><li><b>نسبة التغيّر:</b> $\frac{\text{التغيّر}}{\text{القيمة الأصلية}} \times 100\%$.</li></ul>`,
  '14zii6dfm6x': R`<p>$15\%$ من $240 = 0.15 \times 240 = 36$. &nbsp; طريقة ذهنية: $10\% = 24$ و$5\% = 12$، والمجموع $36$.</p>`,
  '1xvrzy7qz2k': R`<p>نسبة التغيّر نقسمها دائمًا على القيمة <b>الأصلية</b>. إذا ارتفع سعر من 50 إلى 60 فالزيادة $\frac{10}{50} = 20\%$ وليست $\frac{10}{60}$.</p>`,
  '1gobo82ltgo': R`كم يساوي ⟦0⟧% من ⟦1⟧؟`,
  '17t3n1yumuv': R`$⟦0⟧\% \text{ من } ⟦1⟧ = \frac{⟦2⟧}{100} \times ⟦3⟧ = ⟦4⟧$.`,
  'x6d2i6pjon': R`ما النسبة المئوية التي يمثلها ⟦1⟧ من ⟦0⟧؟`,
  '166o0aldzl7': R`اكتب $\frac{⟦0⟧}{⟦1⟧}$ في صورة نسبة مئوية.`,
  '1zxz5pk8y96': R`سعر سترة بالدولار ⟦0⟧، وعليها خصم ⟦1⟧%. ما سعرها بعد الخصم؟`,
  '1fg7th2fl2k': R`دولار`,
  '2d5e1injpmi': R`الخصم $= ⟦0⟧\% \times ⟦1⟧ = ⟦2⟧$. السعر بعد الخصم بالدولار $= ⟦3⟧ - ⟦4⟧ = ⟦5⟧$.`,
  '188c7uiuhvg': R`عدد سكان بلدة ⟦0⟧، وقد زاد بنسبة ⟦1⟧%. ما عدد السكان الجديد؟`,
  '1z4269yh9sc': R`الزيادة $= ⟦0⟧\% \times ⟦1⟧ = ⟦2⟧$. عدد السكان الجديد $= ⟦3⟧ + ⟦4⟧ = ⟦5⟧$.`,
  '24ppsoc883t': R`تغيّر سعر كتاب (بالدولار) من ⟦0⟧ إلى ⟦1⟧. ما النسبة المئوية للزيادة؟`,
  '18zivp6w2kh': R`تغيّر سعر كتاب (بالدولار) من ⟦0⟧ إلى ⟦1⟧. ما النسبة المئوية للنقصان؟`,
  '275khxq1hou': R`مقدار التغيّر بالدولار: ⟦0⟧. نسبة الزيادة: ⟦1⟧ — نقسم دائمًا على السعر <b>الأصلي</b>.`,
  '260avkxsjev': R`مقدار التغيّر بالدولار: ⟦0⟧. نسبة النقصان: ⟦1⟧ — نقسم دائمًا على السعر <b>الأصلي</b>.`,

  // measurement
  'ymwylkippx': R`
<p>يقوم النظام المتري على قوى العدد عشرة، وتدل البادئات على حجم الوحدة.</p>
⟦0⟧
⟦1⟧
⟦2⟧
⟦3⟧
<h3>الزمن</h3>
<p>الزمن <i>ليس</i> عشريًا: في الساعة 60 دقيقة لا 100. لحساب المدة المنقضية تقدّم على مراحل: من 09:35 إلى 13:10 هي 25 د (حتى 10:00) + 3 س (حتى 13:00) + 10 د = 3 س 35 د = 215 دقيقة.</p>
⟦4⟧`,
  '1vt4z8db5g': R`البادئة`,
  '18vrcwaxvwu': R`المعنى`,
  '1j1ms4p35q': R`أمثلة`,
  '1837d2yv17g': R`كيلو (ك)`,
  '6v2px6djsv': R`سنتي (س)`,
  'cwnj8q0jlm': R`ملّي (م)`,
  '4ynf6btmh8': R`الكمية`,
  '1bcl39yblb4': R`التحويلات`,
  '1yt0gqcalpk': R`الطول`,
  '1pzczs2mse4': R`الكتلة`,
  '3r7jg1gvau': R`1 طن = 1,000 كغ · 1 كغ = 1,000 غ`,
  '25cg9l2x1fi': R`السعة`,
  '1ellrod4539': R`الزمن`,
  '149iz1sgt': R`1 د = 60 ث · 1 س = 60 د · 1 يوم = 24 س · 1 أسبوع = 7 أيام`,
  '2g0x2qx5tup': R`<p>عند التحويل من وحدة <b>أكبر</b> إلى وحدة <b>أصغر</b> نحتاج إلى عدد أكبر منها — <b>نضرب</b>. ومن الأصغر إلى الأكبر — <b>نقسم</b>.</p>`,
  'x1upmnco35': R`<p>$3.5 \text{ كم} = 3.5 \times 1000 = 3{,}500 \text{ م}$. &nbsp; $2{,}750 \text{ غ} = 2{,}750 \div 1000 = 2.75 \text{ كغ}$.</p>`,
  't9d9f384y5': R`<p>لا تطرح الأوقات كأنها أعداد عادية: $13{:}10 - 9{:}35$ لا يساوي $1310 - 935 = 375$ دقيقة.</p>`,
  'q3mks7cmvp': R`حوّل ⟦0⟧ ⟦1⟧ إلى ⟦2⟧.`,
  '695i1r66ec': R`من وحدة أكبر إلى وحدة أصغر، لذا نضرب: $⟦0⟧ \times ⟦1⟧ = ⟦2⟧$`,
  '1y3viru9jwt': R`من وحدة أصغر إلى وحدة أكبر، لذا نقسم: $⟦0⟧ \div ⟦1⟧ = ⟦2⟧$`,
  '10b6a48v5cr': R`كم دقيقة في ⟦0⟧ س ⟦1⟧ د؟`,
  '1jj8c6wfcmv': R`دقيقة`,
  '26onbfrmj2m': R`الساعة = 60 دقيقة: $⟦0⟧ \times 60 + ⟦1⟧ = ⟦2⟧$ دقيقة.`,
  '2fcfktfjfb2': R`كم ثانية في ⟦0⟧ د ⟦1⟧ ث؟`,
  '1qje99e2i79': R`الدقيقة = 60 ثانية: $⟦0⟧ \times 60 + ⟦1⟧ = ⟦2⟧$ ثانية.`,
  '1640fwpwscw': R`ينطلق قطار الساعة ⟦0⟧ ويصل الساعة ⟦1⟧ في اليوم نفسه. كم دقيقة تستغرق الرحلة؟`,
  '1bvdcgo9oas': R`من ⟦0⟧ إلى ⟦1⟧ المدة ⟦2⟧ س ⟦3⟧ د، أي $⟦4⟧ \times 60 + ⟦5⟧ = ⟦6⟧$ دقيقة.`,
  'jz7sp6v78m': R`اجمع ⟦0⟧ م ⟦1⟧ سم و⟦2⟧ م ⟦3⟧ سم، واكتب الناتج بالسنتيمتر.`,
  '1v59jh3egmq': R`⟦0⟧ م ⟦1⟧ سم = ⟦2⟧ سم، و⟦3⟧ م ⟦4⟧ سم = ⟦5⟧ سم. المجموع: $⟦6⟧ + ⟦7⟧ = ⟦8⟧$ سم.`,
