  '8exalr20f0': R`الخسارة`,
  '2acjs1v6cv9': R`ت − ب (عندما ب < ت)`,
  '8cl7h0h70q': R`$$\text{نسبة الربح} = \frac{\text{الربح}}{\text{سعر التكلفة}} \times 100\% \qquad\qquad \text{سعر البيع} = \text{سعر التكلفة} \times \left(1 + \frac{p}{100}\right)$$`,
  '2251p3nt91s': R`<p>هاتف اشتُري بـ 400 دولار وبيع بـ 460 دولارًا. الربح $= 60$، إذن نسبة الربح $= \frac{60}{400} \times 100\% = 15\%$.</p>`,
  '16966flk4n0': R`I = P \times r \times t \qquad \text{(المبلغ الأصلي} \times \text{المعدل السنوي} \times \text{عدد السنوات)}`,
  '8dx80n4t33': R`<p>نسبة الربح تُحسب دائمًا من سعر <b>التكلفة</b>، لا من سعر البيع.</p>`,
  'zmoygr0th3': R`اشترى تاجر دراجة ثم باعها. سعر الشراء بالدولار ⟦0⟧، وسعر البيع بالدولار ⟦1⟧. ما نسبة الربح المئوية؟`,
  'hr5vewyo1d': R`اشترى تاجر دراجة ثم باعها. سعر الشراء بالدولار ⟦0⟧، وسعر البيع بالدولار ⟦1⟧. ما نسبة الخسارة المئوية؟`,
  'w2dibc5j0k': R`⟦0⟧ $= ⟦1⟧$. النسبة $= \frac{⟦2⟧}{⟦3⟧} \times 100\% = ⟦4⟧\%$.`,
  '1mg15vgrrsq': R`اشترى متجر مصباحًا سعره بالدولار ⟦0⟧، ويريد ربحًا نسبته ⟦1⟧%. كم يجب أن يكون سعر البيع؟`,
  '1znpgx1zz3k': R`$\text{سعر البيع} = ⟦0⟧ \times ⟦1⟧ = ⟦2⟧$ (بالدولار).`,
  '1qynlkevtzf': R`لمدة سنة واحدة`,
  '265o2h9psz8': R`لمدة ⟦0⟧ من السنوات`,
  'z7uavwhcj6': R`استُثمر مبلغ بالدولار قدره ⟦0⟧ بفائدة بسيطة ⟦1⟧% سنويًا ⟦2⟧. ما المبلغ الكلي في النهاية؟`,
  '158pfsp5k1j': R`استُثمر مبلغ بالدولار قدره ⟦0⟧ بفائدة بسيطة ⟦1⟧% سنويًا ⟦2⟧. كم تبلغ الفائدة؟`,
  '35ywrebltu': R`$I = P r t = ⟦0⟧ \times ⟦1⟧ \times ⟦2⟧ = ⟦3⟧$ (بالدولار).⟦4⟧`,
  '26yfs6y8h5o': R` المجموع $= ⟦0⟧ + ⟦1⟧ = ⟦2⟧$ (بالدولار).`,
  '11eyk8p87p8': R`سعر زوج أحذية بالدولار ⟦0⟧. عليه خصم ⟦1⟧%، ثم تُضاف ضريبة مبيعات ⟦2⟧% إلى السعر بعد الخصم. ما السعر النهائي؟`,
  '1ebjr2t3r5v': R`$⟦0⟧ \times ⟦1⟧ = ⟦2⟧$، ثم $\times ⟦3⟧ = ⟦4⟧$ (بالدولار).`,
  'j3cdki7hbr': R`كيس أرز وزنه القائم ⟦0⟧ كغ. وزن الفارغ ⟦1⟧% من الوزن القائم. ما الوزن الصافي؟`,
  '91s53sp2z': R`الفارغ $= ⟦0⟧\% \times ⟦1⟧ = ⟦2⟧$ كغ. الصافي $= ⟦3⟧ - ⟦4⟧ = ⟦5⟧$ كغ.`,
  '1kvwyquko78': R`بيعت ساعة بربح نسبته ⟦1⟧%، وسعر بيعها بالدولار ⟦0⟧. ما سعر التكلفة؟`,
  'g36e4lpvm4': R`$\text{سعر البيع} = \text{سعر التكلفة} \times ⟦0⟧$، إذن $\text{سعر التكلفة} = \frac{⟦1⟧}{⟦2⟧} = ⟦3⟧$ (بالدولار). (طرح ⟦4⟧% من سعر البيع خطأ.)`,

