  '1zj05x9ucbg': R`أي صيغة تعطي الحد النوني للمتتالية ⟦0⟧, …؟`,
  '10p4kmsov0h': R`تزداد الحدود بمقدار ⟦0⟧، إذن تبدأ الصيغة بـ $⟦1⟧n$. عند $n = 1$: $⟦2⟧(1) + c = ⟦3⟧$ يعطي $c = ⟦4⟧$: $u_n = ⟦5⟧$.`,
  'kmsujsbacm': R`يُضرب كل حد في ⟦0⟧، إذن الحد التالي $⟦1⟧ \times ⟦2⟧ = ⟦3⟧$.`,
  '1tqcntwvtfu': R`أي حد في المتتالية ⟦0⟧, … يساوي ⟦1⟧؟`,
  '1i1kg83c5xj': R`$u_n = ⟦0⟧ + (n - 1) \times ⟦1⟧ = ⟦2⟧$، إذن $(n - 1) \times ⟦3⟧ = ⟦4⟧$، و$n - 1 = ⟦5⟧$، و$n = ⟦6⟧$.`,
  '1ru4k9e3ubn': R`الأعداد المثلثية هي 1, 3, 6, 10, 15, … أوجد العدد المثلثي $T_{⟦0⟧}$.`,
