  '1kfzbnkpyo2': R`تمدد معامله $k$ ومركزه O`,
  '1u5zflf6nl6': R`<p>في الأشكال المتشابهة، الزوايا المتناظرة متساوية والأضلاع المتناظرة متناسبة بنسبة واحدة هي <b>معامل التشابه</b> $k$. المساحات تُضرب في $k^2$ والحجوم في $k^3$.</p>`,
  'f54rct691f': R`<p>المثلثان $ABC$ و$PQR$ متشابهان، و$AB = 6$ و$BC = 8$ و$PQ = 9$. معامل التشابه $k = \frac{9}{6} = 1.5$، إذن $QR = 8 \times 1.5 = 12$. وإذا كانت مساحة المثلث $ABC$ تساوي 24، فمساحة المثلث $PQR$ تساوي $24 \times 1.5^2 = 54$.</p>`,
  '111he4idz8g': R`<p>عمود طوله 1.5 م يُلقي ظلًا طوله 2 م في اللحظة التي تُلقي فيها شجرة ظلًا طوله 12 م. المثلثان متشابهان: $\frac{h}{12} = \frac{1.5}{2}$، إذن $h = 9$ م.</p>`,
  '1ag7324gyvl': R`<p>الأضلاع المتشابهة تختلف بـ<b>عامل ضرب</b>، لا بمقدار ثابت. إذا زاد ضلع من 6 إلى 9، فإن ضلعًا طوله 8 يصبح 12، لا 11.</p>`,
