  '2ettdugdvou': R`دوران $180^\circ$ حول نقطة الأصل`,
  'y4ewc1f7tf': R`دوران $90^\circ$ مع عقارب الساعة حول نقطة الأصل`,
  '147bj1yruac': R`انسحاب بمقدار $⟦0⟧$`,
  'q8g4eu6egm': R`طُبّق على النقطة $P⟦0⟧$ التحويل: ⟦1⟧. ما إحداثيات صورتها؟`,
  'px6a8rprin': R`اكتب الإحداثيات على الصورة x, y.`,
  '199eqilp9e9': R`القاعدة هي ⟦0⟧، إذن الصورة $⟦1⟧$.`,
  '141nr4eramb': R`المثلثان $ABC$ و$PQR$ متشابهان، حيث $AB \leftrightarrow PQ$ و$BC \leftrightarrow QR$ و$CA \leftrightarrow RP$. إذا كان $AB = ⟦0⟧$ و$BC = ⟦1⟧$ و$CA = ⟦2⟧$ و$⟦3⟧ = ⟦4⟧$، فأوجد $⟦5⟧$.`,
  '1kimjtrunz7': R`معامل التشابه $k = \frac{⟦0⟧}{⟦1⟧} = ⟦2⟧$. إذن $⟦3⟧ = ⟦4⟧ \times ⟦5⟧ = ⟦6⟧$.`,
  'bj1shpkj9u': R`مجسمان متشابهان معامل التشابه بينهما ⟦0⟧. حجم الأصغر ⟦1⟧ سم³. ما حجم الأكبر؟`,
  'ld6jtpizu2': R`الحجوم تُضرب في $k^3 = ⟦0⟧$: $⟦1⟧ \times ⟦2⟧ = ⟦3⟧$ سم³.`,
  '11duhh78e55': R`شكلان متشابهان معامل التشابه بينهما ⟦0⟧. مساحة الأصغر ⟦1⟧ سم². ما مساحة الأكبر؟`,
  'hfezjn5dnm': R`المساحات تُضرب في $k^2 = ⟦0⟧$: $⟦1⟧ \times ⟦2⟧ = ⟦3⟧$ سم².`,
  '2eojcpktunl': R`عصا طولها ⟦0⟧ م تُلقي ظلًا طوله ⟦1⟧ م. وفي اللحظة نفسها تُلقي شجرة ظلًا طوله ⟦2⟧ م. ما ارتفاع الشجرة؟`,
  '196fpe0msid': R`المثلثان متشابهان: $\frac{h}{⟦0⟧} = \frac{⟦1⟧}{⟦2⟧}$، إذن $h = ⟦3⟧ \times \frac{⟦4⟧}{⟦5⟧} = ⟦6⟧$ م.`,
  '1iy8baeb4jd': R`طُبّق على النقطة $⟦0⟧$ تمدد مركزه نقطة الأصل ومعامله ⟦1⟧. أين تقع صورتها؟`,
  '1fyw56nqicr': R`اضرب الإحداثيين كليهما في ⟦0⟧: $(⟦1⟧ \times ⟦2⟧,\; ⟦3⟧ \times ⟦4⟧) = ⟦5⟧$.`,
