  '2eim40ubkm5': R`x^2 - x - 12 = 0 \;\Rightarrow\; (x - 4)(x + 3) = 0 \;\Rightarrow\; x = 4 \text{ أو } x = -3`,
  '2fswinarukx': R`$$x = \frac{-b \pm \sqrt{b^2 - 4ac}}{2a}$$<p><b>المميِّز</b> $D = b^2 - 4ac$ يحدد عدد الجذور الحقيقية:</p><ul><li>$D \gt 0$: جذران حقيقيان مختلفان</li><li>$D = 0$: جذر حقيقي مكرر</li><li>$D \lt 0$: لا توجد جذور حقيقية (جذران مركّبان)</li></ul>`,
  '2es7ki62fmx': R`<p>$2x^2 - 7x + 3 = 0$: $D = 49 - 24 = 25$، إذن $x = \frac{7 \pm 5}{4}$، أي $x = 3$ أو $x = \frac{1}{2}$. التحقق: المجموع $= \frac{7}{2}$ ✓، وحاصل الضرب $= \frac{3}{2}$ ✓.</p>`,
  '2fn72wvlok5': R`<p>لا تقسم الطرفين على $x$ أبدًا — ستفقد الجذر $x = 0$. انقل كل الحدود إلى طرف واحد وحلّل.</p>`,
