  '23qtrsvpbqj': R`مجموع الجذرين $= -\frac{b}{a} = ⟦0⟧$.`,
  '2e310dsl6wd': R`أوجد حاصل ضرب جذري المعادلة $⟦0⟧ = 0$.`,
