  '205beb6gfix': R`
⟦0⟧
<h3>التباديل: الترتيب مهم</h3>
⟦1⟧
<p>الجوائز الأولى والثانية والثالثة بين 10 أشخاص: $^{10}P_3 = 10 \times 9 \times 8 = 720$.</p>
<ul><li>ترتيبات بعناصر مكررة: $\frac{n!}{p!\,q!\cdots}$. لكلمة «BANANA» عدد $\frac{6!}{3!\,2!} = 60$ ترتيبًا.</li><li>حول دائرة: $(n - 1)!$ (الدورانات تُعدّ ترتيبًا واحدًا).</li></ul>
<h3>التوافيق: الترتيب غير مهم</h3>
⟦2⟧
<p>لجنة من 3 أشخاص من بين 10: $\binom{10}{3} = 120$. لجنة من رجلين (من 5) و3 نساء (من 6): $\binom{5}{2}\binom{6}{3} = 10 \times 20 = 200$.</p>
<h3>مبرهنة ذات الحدين</h3>
⟦3⟧
<p>معامل $x^2$ في $(x + 3)^5$ هو $\binom{5}{2}3^{3} = 270$.</p>
⟦4⟧`,
  '1v1ul4mcyis': R`<p><b>مبدأ الضرب:</b> إذا أمكن إجراء اختيار بـ $m$ طريقة واختيار ثانٍ بـ $n$ طريقة، فإنه يمكن إجراؤهما معًا بـ $m \times n$ طريقة.</p>`,
  'zol45txfa7': R`^nP_r = \frac{n!}{(n - r)!} \qquad n! = n \times (n-1) \times \cdots \times 1, \quad 0! = 1`,
  '1mk1wwf7o0g': R`^nC_r = \binom{n}{r} = \frac{n!}{r!\,(n - r)!}`,
  '44tf1m2pka': R`<p>اسأل نفسك: «هل يعطي تبديل عنصرين مختارين نتيجة مختلفة؟» إذا كان الجواب نعم فاستخدم التباديل، وإلا فالتوافيق.</p>`,
  'asaw2vy5ho': R`بكم طريقة يمكن منح الجوائز (⟦0⟧) بين ⟦1⟧ شخصًا؟`,
  '1qec64m00zt': R`الأولى والثانية والثالثة`,
  '1yxzw7y67ed': R`الأولى والثانية`,
  '1lyu4ddmyjw': R`الترتيب مهم: $^{⟦0⟧}P_{⟦1⟧} = ⟦2⟧ = ⟦3⟧$.`,
  'mt1d3k54sw': R`بكم طريقة يمكن اختيار لجنة عدد أعضائها ⟦0⟧ من بين ⟦1⟧ شخصًا؟`,
  'jcb5dbxzw7': R`الترتيب غير مهم: $\binom{⟦0⟧}{⟦1⟧} = \frac{⟦2⟧!}{⟦3⟧!\,⟦4⟧!} = ⟦5⟧$.`,
  '1f3hbyul4kh': R`تُختار لجنة فيها من الرجال: ⟦0⟧، ومن النساء: ⟦1⟧، من بين مجموعة فيها من الرجال: ⟦2⟧، ومن النساء: ⟦3⟧. كم لجنة مختلفة يمكن تكوينها؟`,
  '219eq0t6hby': R`كم ترتيبًا مختلفًا يوجد لحروف الكلمة <b>⟦0⟧</b>؟`,
  'hkyvcodvcm': R`عدد الحروف ⟦0⟧ مع التكرارات ⟦1⟧: $\frac{⟦2⟧!}{⟦3⟧} = ⟦4⟧$.`,
  'qqcdrtkh5v': R`بكم طريقة يمكن أن يجلس ⟦0⟧ أشخاص حول طاولة مستديرة (الدورانات تُعدّ ترتيبًا واحدًا)؟`,
  '1n6howxe7gj': R`ثبّت مقعد شخص واحد لإلغاء الدورانات، ثم رتّب الباقين: $(⟦0⟧ - 1)! = ⟦1⟧$.`,
  '1hwymhgsxow': R`أوجد معامل $x^{⟦0⟧}$ في مفكوك $(x + ⟦1⟧)^{⟦2⟧}$.`,
  '22kaf86ykzl': R`الحد الذي يحوي $x^{⟦0⟧}$ هو $\binom{⟦1⟧}{⟦2⟧}x^{⟦3⟧}\cdot ⟦4⟧^{⟦5⟧}$، إذن المعامل $⟦6⟧ \times ⟦7⟧ = ⟦8⟧$.`,
  '1zya3uq0ode': R`أوجد معامل $x^{⟦0⟧}$ في مفكوك $(⟦1⟧x + 1)^{⟦2⟧}$.`,
  'po66a6fw7b': R`الحد الذي يحوي $x^{⟦0⟧}$ هو $\binom{⟦1⟧}{⟦2⟧}(⟦3⟧x)^{⟦4⟧}$، إذن المعامل $⟦5⟧ \times ⟦6⟧ = ⟦7⟧$.`,
  'yh0td3xino': R`لديك قمصان عددها ⟦0⟧، وسراويل عددها ⟦1⟧، وأزواج أحذية عددها ⟦2⟧. كم طقمًا مختلفًا (قطعة من كل نوع) يمكنك تكوينه؟`,
  'ruo6vpaqqc': R`مبدأ الضرب: $⟦0⟧ \times ⟦1⟧ \times ⟦2⟧ = ⟦3⟧$.`,
  '24djh3i5509': R`كم رمزًا سريًا مكوّنًا من ⟦0⟧ أرقام يمكن تكوينه من الأرقام 0–9 ⟦1⟧؟`,
  '1djueshnkes': R`إذا سُمح بتكرار الأرقام`,
