  'xux9y4rrwd': R`$P(A \cap B) = 0$، إذن $P(A \cup B) = P(A) + P(B)$`,
  'rl5n9i6yyd': R`حدثان مستقلان`,
  '1oou6k826kr': R`احتمال شرطي`,
  '1qgmh66fhna': R`<p>كيس فيه 5 كرات حمراء و3 كرات زرقاء. تُسحب كرتان <b>دون</b> إرجاع. $P(\text{الكرتان حمراوان}) = \frac{5}{8} \times \frac{4}{7} = \frac{5}{14}$. ومع الإرجاع يكون $\frac{5}{8} \times \frac{5}{8} = \frac{25}{64}$.</p>`,
  '6418q9b2s4': R`$$P(A \mid B) = \frac{P(B \mid A)\,P(A)}{P(B \mid A)P(A) + P(B \mid A')P(A')}$$<p>إنها «تعكس» الاحتمال الشرطي — مثلًا من $P(\text{فحص إيجابي} \mid \text{مرض})$ إلى $P(\text{مرض} \mid \text{فحص إيجابي})$.</p>`,
  '1zp2m1asa8t': R`<p>$P(A \mid B)$ و$P(B \mid A)$ مختلفان عادةً. قد تبلغ دقة فحص 99%، ومع ذلك قد تكون النتيجة الإيجابية إنذارًا كاذبًا على الأرجح عندما يكون المرض نادرًا.</p>`,
  '5fmcyqy5g8': R`كيس فيه كرات حمراء عددها ⟦0⟧ وكرات زرقاء عددها ⟦1⟧. تُسحب كرتان دون إرجاع. ما احتمال أن تكون الكرتان كلتاهما ⟦2⟧؟`,
  '16uk5urbde9': R`$P(A) = ⟦0⟧$ و$P(B) = ⟦1⟧$ و$P(A \cap B) = ⟦2⟧$. أوجد $P(A \cup B)$.`,
  '2az4z9znymk': R`الحدثان $A$ و$B$ مستقلان، و$P(A) = ⟦0⟧$ و$P(B) = ⟦1⟧$. أوجد $P(A \cap B)$.`,
  '1ohoi8ye65': R`مستقلان: $P(A \cap B) = ⟦0⟧ \times ⟦1⟧ = ⟦2⟧$.`,
  'ymjaeaaedm': R`الحدثان $A$ و$B$ مستقلان، و$P(A) = ⟦0⟧$ و$P(B) = ⟦1⟧$. أوجد احتمال وقوع أحدهما على الأقل.`,
  'y6o9k7peax': R`$1 - P(\text{عدم وقوع أي منهما}) = 1 - (⟦0⟧)(⟦1⟧) = ⟦2⟧$.`,
  '2ct3qu61tjb': R`الأولاد`,
