  '1mojcap1eui': R`أعطى استطلاع هذه النتائج.⟦0⟧اختير شخص عشوائيًا. إذا علمت أنه من المجموعة «⟦1⟧»، فما احتمال أن يكون من «⟦2⟧»؟`,
  '1461hv2wfqt': R`اقتصر على أفراد «⟦1⟧» وعددهم ⟦0⟧: $P = \frac{⟦2⟧}{⟦3⟧} = ⟦4⟧$.`,
  '12180tm9why': R`أعطى استطلاع هذه النتائج.⟦0⟧اختير شخص عشوائيًا. إذا علمت أنه من «⟦1⟧»، فما احتمال أن يكون من المجموعة «⟦2⟧»؟`,
  'eppqyrg22a': R`يُرمى حجر نرد منتظم، وعدد الرميات ⟦0⟧. ما احتمال الحصول على ستة مرة واحدة على الأقل؟`,
  'wzrge9rclz': R`$1 - P(\text{لا ستة}) = 1 - \left(\frac{5}{6}\right)^{⟦0⟧} = 1 - \frac{⟦1⟧}{⟦2⟧} = ⟦3⟧$.`,
  '1sg12en11ty': R`يصيب مرض ⟦0⟧% من الناس. يكشف فحصٌ المرضَ لدى ⟦1⟧% من المصابين، لكنه يعطي نتيجة إيجابية أيضًا لدى ⟦2⟧% من غير المصابين. إذا كانت نتيجة فحص شخص إيجابية، فما احتمال أن يكون مصابًا؟ قرّب إلى 3 منازل عشرية.`,
  '1n6kg7z10yy': R`كيس فيه قطع حمراء عددها ⟦0⟧ وقطع زرقاء عددها ⟦1⟧. تُسحب قطعة ثم تُعاد، ثم تُسحب قطعة ثانية. ما احتمال أن تكون الأولى حمراء والثانية زرقاء؟`,
  '29cd8gay3w4': R`مع الإرجاع يكون السحبان مستقلين: $\frac{⟦0⟧}{⟦1⟧} \times \frac{⟦2⟧}{⟦3⟧} = ⟦4⟧$.`,

