  'l167vch4m7': R`<p>قاعدة شائعة للقيم المتطرفة: القيم الأصغر من $Q_1 - 1.5\,\text{IQR}$ أو الأكبر من $Q_3 + 1.5\,\text{IQR}$.</p>`,
  '1i22g7xb1dd': R`\sigma^2 = \frac{\sum (x - \mu)^2}{n} \qquad \sigma = \sqrt{\sigma^2} \qquad\qquad s^2 = \frac{\sum (x - \bar{x})^2}{n - 1} \text{ (عيّنة)}`,
  '1c6crwakkdh': R`<p>البيانات 2، 4، 4، 4، 5، 5، 7، 9: الوسط 5، ومربعات الانحرافات 9، 1، 1، 1، 0، 0، 4، 16 (المجموع 32). تباين المجتمع $= \frac{32}{8} = 4$ و$\sigma = 2$.</p>`,
  'etseh8nv9i': R`إذا أصبحت كل قيمة`,
