  's70utdhfyg': R`$\sigma$ (لا يتغير)`,
  '1ixl32zcrbx': R`<p>إضافة ثابت تُزيح البيانات لكنها لا تزيد تشتتها، لذا يبقى الانحراف المعياري كما هو.</p>`,
  '1os4b58x5gr': R`أوجد تباين <b>العيّنة</b> للبيانات: ⟦0⟧.`,
  '5koevyyrqx': R`أوجد تباين <b>المجتمع</b> للبيانات: ⟦0⟧.`,
  '2gl7bcglff0': R`الوسط $= ⟦0⟧$. مربعات الانحرافات: ⟦1⟧ (المجموع ⟦2⟧). القسمة على ⟦3⟧: $⟦4⟧$.`,
  'zh9si0i2s': R`أوجد الانحراف المعياري للمجتمع للبيانات: ⟦0⟧. قرّب إلى منزلتين عشريتين.`,
  'iohahpasm4': R`الوسط $= ⟦0⟧$؛ $\sigma^2 = \frac{⟦1⟧}{5} = ⟦2⟧$، إذن $\sigma = \sqrt{⟦3⟧} \approx ⟦4⟧$.`,
  'box0w6rodc': R`أوجد المدى الربيعي للبيانات: ⟦0⟧. (استبعد الوسيط عند تقسيم البيانات إلى نصفين.)`,
  'dvfyzp44sk': R`بعد الترتيب: ⟦0⟧. النصف الأدنى ⟦1⟧ يعطي $Q_1 = ⟦2⟧$؛ والنصف الأعلى ⟦3⟧ يعطي $Q_3 = ⟦4⟧$. $\text{IQR} = ⟦5⟧ - ⟦6⟧ = ⟦7⟧$.`,
  '25jr4jzamls': R`مجموعة بيانات وسطها ⟦0⟧ وانحرافها المعياري ⟦1⟧. تُحوَّل كل قيمة وفق $y = ⟦2⟧x ⟦3⟧$. ما الانحراف المعياري الجديد؟`,
  '1h7x4xfpmhw': R`إضافة ⟦0⟧ لا تغيّر التشتت؛ والضرب في ⟦1⟧ يضاعفه بالعامل $|⟦2⟧|$: $⟦3⟧ \times ⟦4⟧ = ⟦5⟧$.`,
  '158l5v4dkra': R`مجموعة بيانات وسطها ⟦0⟧ وانحرافها المعياري ⟦1⟧. تُحوَّل كل قيمة وفق $y = ⟦2⟧x ⟦3⟧$. ما الوسط الجديد؟`,
  '21c6bmoi3b4': R`الوسط يتبع التحويل نفسه: $⟦0⟧(⟦1⟧) ⟦2⟧ = ⟦3⟧$.`,
  'th9c52kib0': R`قدّر الوسط الحسابي من جدول التوزيع التكراري المبوّب الآتي (استخدم مراكز الفئات). قرّب إلى منزلتين عشريتين.⟦0⟧`,
  '1h8qh0j4anc': R`الفئة`,
  '1yeuaowmmsc': R`مراكز الفئات ⟦0⟧؛ $\sum f = ⟦1⟧$، $\sum fm = ⟦2⟧$. الوسط $\approx \frac{⟦3⟧}{⟦4⟧} ⟦5⟧ ⟦6⟧$.`,
  '1kja7bg5lcu': R`مجموعة بيانات فيها $Q_1 = ⟦0⟧$ و$Q_3 = ⟦1⟧$. باستخدام قاعدة $1.5 \times \text{IQR}$، ما الحد ⟦2⟧ للقيم المتطرفة؟`,
