  '12p1gvv8rrs': R`
⟦0⟧
<h3>معادلة الدائرة</h3>
⟦1⟧
<p>بفك الأقواس نحصل على <b>الصيغة العامة</b> $x^2 + y^2 + Dx + Ey + F = 0$، ومركزها $\left(-\frac{D}{2}, -\frac{E}{2}\right)$ ونصف قطرها $r = \sqrt{\frac{D^2}{4} + \frac{E^2}{4} - F}$.</p>
⟦2⟧
<h3>موقع نقطة</h3>
<p>عوّض النقطة في $(x - a)^2 + (y - b)^2$ وقارن بـ $r^2$: أصغر ← داخل الدائرة، يساوي ← عليها، أكبر ← خارجها.</p>
<h3>المماسات</h3>
<p>المماس عمودي على نصف القطر عند نقطة التماس. للدائرة $x^2 + y^2 = r^2$ عند $(x_1, y_1)$، ميل نصف القطر $\frac{y_1}{x_1}$، إذن ميل المماس $-\frac{x_1}{y_1}$.</p>
<h3>القطوع المكافئة</h3>
<p>للقطع $y^2 = 4px$ بؤرة $(p, 0)$ ودليل $x = -p$؛ وللقطع $x^2 = 4py$ بؤرة $(0, p)$ ودليل $y = -p$. كل نقطة على القطع المكافئ بُعدها عن البؤرة يساوي بُعدها عن الدليل.</p>
⟦3⟧`,
  'd8g3n0gso0': R`\text{المنتصف } \left(\frac{x_1 + x_2}{2}, \frac{y_1 + y_2}{2}\right) \qquad \text{المسافة } \sqrt{(x_2 - x_1)^2 + (y_2 - y_1)^2}`,
  'yeziymovo4': R`$$(x - a)^2 + (y - b)^2 = r^2 \qquad \text{المركز } (a, b), \text{ نصف القطر } r$$`,
  '16n3xjnynm7': R`<p>$x^2 + y^2 - 6x + 4y - 12 = 0$: بإكمال المربعات، $(x - 3)^2 + (y + 2)^2 = 12 + 9 + 4 = 25$. المركز $(3, -2)$ ونصف القطر 5.</p>`,
  '11ib4pk61jv': R`<p>في $(x + 3)^2 + (y - 1)^2 = 16$ المركز هو $(-3, 1)$ — الإشارات تنعكس — ونصف القطر 4 وليس 16.</p>`,
  'a19ymany96': R`أوجد منتصف القطعة الواصلة بين $⟦0⟧$ و$⟦1⟧$.`,
  'l7s72risy9': R`خذ متوسط الإحداثيات: $\left(\frac{⟦0⟧ + ⟦1⟧}{2}, \frac{⟦2⟧ + ⟦3⟧}{2}\right) = ⟦4⟧$.`,
  '1mu3r9x32jw': R`أوجد نصف قطر الدائرة $⟦0⟧ = 0$.`,
  '1bhxlcedykj': R`بإكمال المربعات: $(x ⟦0⟧)^2 + (y ⟦1⟧)^2 = ⟦2⟧ + ⟦3⟧ ⟦4⟧ = ⟦5⟧$، إذن $r = ⟦6⟧$.`,
  'd11etx15kp': R`أوجد مركز الدائرة $⟦0⟧ = 0$.`,
  '15nydo8wzsx': R`المركز هو $\left(-\frac{D}{2}, -\frac{E}{2}\right) = \left(-\frac{⟦0⟧}{2}, -\frac{⟦1⟧}{2}\right) = ⟦2⟧$.`,
  '10fdmgbsvjs': R`ما معادلة الدائرة التي مركزها $⟦0⟧$ ونصف قطرها ⟦1⟧؟`,
  'j31butbqt0': R`بالتعويض في $(x - a)^2 + (y - b)^2 = r^2$: $(x ⟦0⟧)^2 + (y ⟦1⟧)^2 = ⟦2⟧$.`,
  'qntj72wic0': R`داخل الدائرة`,
  '1z2fjcjol1w': R`داخل`,
  '1h4trl2qo1h': R`على الدائرة`,
  '1sg9ogxwlev': R`على`,
  '8uau8fsxbq': R`خارج الدائرة`,
  '6gv2pbcp7q': R`خارج`,
  '24luyo2ftju': R`هل النقطة $⟦0⟧$ داخل الدائرة $(x ⟦1⟧)^2 + (y ⟦2⟧)^2 = ⟦3⟧$ أم عليها أم خارجها؟`,
  '28keqi93flp': R`$⟦0⟧$، وهو يساوي $r^2 = ⟦1⟧$: النقطة <b>على</b> الدائرة.`,
  '1hj2pbrwkr7': R`$⟦0⟧$، وهو أصغر من $r^2 = ⟦1⟧$: النقطة <b>داخل</b> الدائرة.`,
  'kv7senj1fr': R`$⟦0⟧$، وهو أكبر من $r^2 = ⟦1⟧$: النقطة <b>خارج</b> الدائرة.`,
  '1hxz2qew8oz': R`أوجد بؤرة القطع المكافئ $⟦0⟧$.`,
  '22fls2lezk5': R`بالمقارنة مع ⟦0⟧: $4p = ⟦1⟧$، إذن $p = ⟦2⟧$ والبؤرة هي $⟦3⟧$.`,
  'ez3m02hgj1': R`أوجد ميل المماس للدائرة $x^2 + y^2 = ⟦0⟧$ عند النقطة $⟦1⟧$.`,
  '1huwumypuyf': R`ميل نصف القطر إلى $⟦0⟧$ هو $\frac{⟦1⟧}{⟦2⟧}$. المماس عمودي عليه: الميل $= -\frac{⟦3⟧}{⟦4⟧} = ⟦5⟧$.`,

  // linear-programming
  '23l7ef2fdyh': R`
<p><b>البرمجة الخطية</b> تبحث عن أفضل قيمة (أكبر قيمة أو أصغرها) لـ<b>دالة هدف</b> خطية، مثل الربح $z = 30x + 20y$، في ظل <b>قيود</b> خطية مثل $x + y \le 40$.</p>
<ol><li>اكتب القيود على شكل متباينات (ومنها $x \ge 0$ و$y \ge 0$).</li><li>ارسم كل خط حدودي وظلّل المنطقة التي تحقق جميع القيود — <b>منطقة الحلول الممكنة</b>.</li><li>أوجد الرؤوس بحل كل زوج من معادلات الحدود.</li><li>احسب دالة الهدف عند كل رأس.</li></ol>
⟦0⟧
⟦1⟧
<p>في مسائل التصغير ذات القيود «≥» تكون المنطقة غالبًا غير محدودة؛ ومع التكاليف الموجبة تبقى القيمة الصغرى عند أحد الرؤوس.</p>
⟦2⟧`,
  'hs1573xprv': R`<p><b>مبرهنة الرؤوس:</b> إذا وُجدت قيمة مثلى، فإنها تتحقق عند رأس من رؤوس منطقة الحلول الممكنة.</p>`,
  '1g8qhbmqb9w': R`<p>أوجد القيمة العظمى لـ $z = 3x + 2y$ في ظل $x + y \le 8$ و$2x + y \le 12$ و$x, y \ge 0$.</p><p>الرؤوس: $(0, 0)$ و$(6, 0)$ و$(4, 4)$ [تقاطع $x + y = 8$ مع $2x + y = 12$] و$(0, 8)$.</p><p>قيم $z$: 0، 18، 20، 16. القيمة العظمى $z = 20$ عند $(4, 4)$.</p>`,
  '11p3z90h4pd': R`<p>تحقّق من أن كل رأس يحقق <b>جميع</b> القيود — فقد يقع تقاطع خطين حدوديين خارج المنطقة.</p>`,
  '22hgo1z3v51': R`أوجد القيمة العظمى لـ $z = ⟦0⟧ + ⟦1⟧$ في ظل ⟦2⟧ و$x \ge 0$ و$y \ge 0$. ما القيمة العظمى لـ $z$؟`,
  'thttp4dv20': R`الرؤوس وقيم $z$: ⟦0⟧. القيمة العظمى هي <b>⟦1⟧</b>.`,
  '2g9b1szo820': R`أوجد القيمة الصغرى لـ $z = ⟦0⟧ + ⟦1⟧$ في ظل $x + y \ge ⟦2⟧$ و$x + 2y \ge ⟦3⟧$ و$x \ge 0$ و$y \ge 0$. ما القيمة الصغرى لـ $z$؟`,
  '72m6dlh1yr': R`منطقة الحلول الممكنة غير محدودة، ورؤوسها ⟦0⟧. بما أن التكاليف موجبة، فالقيمة الصغرى هي <b>⟦1⟧</b>.`,
  '4eos6o7rio': R`أي نقطة تقع في منطقة الحلول الممكنة المحددة بـ ⟦0⟧ و$x \ge 0$ و$y \ge 0$؟`,
  '1jqzy1kt3ra': R`اختبر كل نقطة في كل قيد. النقطة $⟦0⟧$ تحقق جميع القيود؛ وكل نقطة من النقاط الأخرى تخالف قيدًا واحدًا على الأقل.`,
  '15d4uuzw5eq': R`مخبز يصنع كل يوم كعكات ($x$) وفطائر ($y$). يمكنه خَبز ⟦0⟧ قطعة على الأكثر، ووقت الخَبز يعطي القيد ⟦1⟧. الربح بالدولار ⟦2⟧ لكل كعكة و⟦3⟧ لكل فطيرة. ما أكبر ربح يومي؟`,
  '296rrmt4h4q': R`القيود: $x + y \le ⟦0⟧$، $⟦1⟧ \le ⟦2⟧$، $x, y \ge 0$. الرؤوس: ⟦3⟧. أكبر ربح بالدولار: <b>⟦4⟧</b>.`,

  // logic
  '22xng4phovn': R`
<p><b>القضية</b> جملة إمّا صائبة وإمّا خاطئة. تُبنى القضايا المركبة باستخدام <b>أدوات الربط</b>:</p>
⟦0⟧
⟦1⟧
<h3>العكس والمعكوس والمعاكس الإيجابي</h3>
⟦2⟧
<h3>المكمِّمات</h3>
<p>$\forall$ «لكل» و$\exists$ «يوجد». النفي يبدّل بينهما: نفي «نجح جميع الطلاب» هو «<b>بعض</b> الطلاب <b>لم</b> ينجحوا»؛ ونفي «بعض الطيور لا تطير» هو «جميع الطيور تطير».</p>
<h3>الاستدلالات الصحيحة</h3>
<ul><li><b>قاعدة الإثبات:</b> $p \Rightarrow q$، $p$؛ إذن $q$.</li><li><b>قاعدة النفي:</b> $p \Rightarrow q$، $\neg q$؛ إذن $\neg p$.</li><li><b>القياس:</b> $p \Rightarrow q$، $q \Rightarrow r$؛ إذن $p \Rightarrow r$.</li></ul>
⟦3⟧`,
  '2aa32u1lmw9': R`صخ`,
  '1h0id2d836q': R`<p>الاستلزام $p \Rightarrow q$ خاطئ <b>فقط</b> عندما تكون $p$ صائبة و$q$ خاطئة.</p>`,
