  '2377erd9rpv': R`نعم`,
  '1vdptccpewy': R`<p>من $p \Rightarrow q$ و$q$ <b>لا يمكن</b> استنتاج $p$ («إثبات التالي» مغالطة). الأرض المبتلة لا تثبت أن المطر هطل.</p>`,
  'e62y0oj6y7': R`قيمة $p$: ⟦0⟧، وقيمة $q$: ⟦1⟧، وقيمة $r$: ⟦2⟧. ما قيمة الصواب للقضية $⟦3⟧$؟`,
  'x0xbdvafwl': R`عوّض $p = \text{⟦0⟧}$ و$q = \text{⟦1⟧}$ و$r = \text{⟦2⟧}$ واحسب من الداخل إلى الخارج: $⟦3⟧$ <b>⟦4⟧</b>. (تذكّر: $\Rightarrow$ خاطئ فقط في الحالة ص ⇒ خ.)`,
