  '14dtm0889wo': R`ما <b>⟦0⟧</b> للقضية «⟦1⟧»؟`,
  '1izj6udg2zz': R`العكس: نبدّل ($q \Rightarrow p$). المعكوس: ننفي الطرفين ($\neg p \Rightarrow \neg q$). المعاكس الإيجابي: نبدّل وننفي ($\neg q \Rightarrow \neg p$). إذن ⟦0⟧ هو «⟦1⟧»⟦2⟧`,
