  'b5r03m1c02': R`ما نفي «⟦0⟧»؟`,
  '1a591wdfgbv': R`$\neg(\forall x\, P(x)) \equiv \exists x\, \neg P(x)$: يكفي أن يخفق <i>بعضهم</i>. النفي: «⟦0⟧»`,
  'do28na3fol': R`$\neg(\exists x\, P(x)) \equiv \forall x\, \neg P(x)$: لا أحد منهم يحققها. النفي: «⟦0⟧»`,
  'ndnufyumww': R`كم صفًا في جدول الصواب لقضية فيها من المتغيرات المختلفة: ⟦0⟧؟`,
  'u75a1of7f2': R`كل متغير إمّا ص أو خ، إذن توجد $2^{⟦0⟧} = ⟦1⟧$ حالة.`,
