  '1h3hboouplr': R`المقدمة 1: «إذا صحّ أنّ ⟦0⟧ فإنّ ⟦1⟧.» المقدمة 2: «⟦2⟧.» ما الذي يمكن استنتاجه استنتاجًا صحيحًا؟`,
  '19xzw2kl48j': R`هذه قاعدة الإثبات ($p \Rightarrow q$، $p$ ⊢ $q$): «⟦0⟧.»`,
